import{i as e,n as t,r as n,t as r}from"./zh-Hans-vZKB7cQS.js";import{a as i,c as a,i as o,l as s,n as c,o as l,r as u,s as d,t as f,u as p}from"./zh-Hans-JaumcI07.js";import{n as m,r as h,t as g}from"./zh-Hans-CqDZ-pNd2.js";import{t as _}from"./zh-Hans-sZ9aav-o.js";import{i as v,n as y,r as b,t as x}from"./zh-Hans-BJ6c1q7P.js";var S={Fi:()=>`高级模型选择`,Fj:e,Fk:()=>`适用于元数据缺失、格式未知或读取失败的情况。未识别的模型仍可选择，但生成时仍会验证模型，并可能提示不支持。`,Fl:_,Fm:p,Fn:s,Fp:a,Fq:d,Fr:l,Fs:()=>`Cancel and discard`,Ft:()=>`Get audio so far`,Fv:n,Fw:()=>`正在检查本地模型元数据…`,Fx:t,Fz:()=>`The prompt needs more context. Shorten the text/reference or increase the context size.`,FA:()=>`这是请求的上下文大小。实际分配不超过模型的训练上下文，内存不足时可能缩小。更大的上下文会占用更多内存，但不会加快生成。它与音频生成步数上限是不同的设置。`,FB:i,FE:v,FF:()=>`正在解码生成的音频…`,FG:()=>`删除所有音频`,FN:()=>`The model produced no audio samples. Check the model pair and try a short sentence with a different seed.`,FO:()=>`Finish generation and keep audio`,FP:()=>`Finish generation and keep audio ends further steps. Cancel and discard drops audio not yet captured. Audio already added to history remains.`,FR:()=>`Finishing the current step, then converting the audio…`,FS:()=>`Generate audio`,FT:b,FU:()=>`Audio generation failed. Report the code below and the [llama-cpp-browser] console diagnostics. GPU failures may require selecting CPU and trying again.`,FW:()=>`Generation stopped. No partial audio was published.`,FX:({count:e,mebibytes:t})=>`${e} 条结果 · 音频数据 ${t} MiB（播放器另占内存）`,FY:()=>`Enter a short sentence for the first test.`,FZ:o,F_:()=>`独立的浏览器本地语音生成工作区。应用、运行环境和模型已保存在本地时，可离线生成。文本和参考音频不会发送到推理服务器；仅下载尚未获取的文件或更新时需要网络。`,Ga:r,Gd:u,Ge:()=>`如果支持，初始语言会与应用的显示语言一致。请明确选择朗读语言。Qwen 的模型默认语言是英语，并非自动检测。Pocket 使用模型训练时的语言，不受此设置影响。`,Gg:()=>`Models and runtime`,Gh:c,Gk:y,Gl:()=>`通过本地模型及其选定音频辅助模型的元数据筛选候选项。这不保证兼容性或音质。检查不会为推理加载模型，也不会下载模型。`,Gm:()=>`Import a matching backbone GGUF and audio mmproj together as one model folder, or download the pair with the repository browser below. Keep only one backbone (or its shards) and one matching mmproj in the folder. Chat model suggestions are not shown here.`,Gn:()=>`Supported native pipelines: Qwen3-TTS Base and Pocket TTS. CustomVoice and VoiceDesign are not supported by this screen. Compatibility is checked after loading, not guessed from filenames. Runtime profile settings are shared with browser chat inference.`,Go:()=>`Detailed native diagnostics in the console`,Gp:()=>`未检测到音频生成候选模型。`,Gr:()=>`未识别为音频生成模型`,Gt:()=>`此页面打开期间，已完成的音频和设置会保留在内存中，包括下一次生成期间。可逐条或全部删除以释放它们。不会自动保存，请在离开或刷新页面前保存需要的 WAV。不会自动播放。`,Gv:()=>`Preparing selected reference audio…`,Gw:()=>`Adds audio so far to history without ending generation. Qwen waits for a completed waveform block; short requests may finish before a preview is available. No automatic playback.`,Gx:()=>`Waiting for a safe audio boundary. Generation will continue.`,Gz:()=>`此设置仅控制音频辅助模型，主模型仍遵循共享运行配置。跟随配置时可使用WebGPU，但部分运算仍可能在CPU上执行。强制CPU可能更慢，可用于比较和排查。`,GN:()=>`Pocket requires a reference voice. Choose an audio file and try again.`,GS:()=>`重新初始化运行环境`,GT:()=>`发生运行错误后，无需刷新页面即可重新初始化。已保存的模型、文本和音频记录会保留，不会中断其他正在运行的任务。`,GU:()=>`正在重新初始化运行环境…`,GX:x,GY:()=>`Open Models and runtime to select an available runtime and import a matching model pair.`,GZ:()=>`Token sampling controls apply to Qwen’s backbone. Top K, top P and seed also pass to the native audio helper. Pocket ignores token sampling and uses its native defaults. Temperature 0 does not guarantee deterministic audio. Step counts are not a predicted completion percentage or a fixed duration.`,G_:f,Hb:()=>`显示所有已保存的 llama.cpp browser 模型`,Hc:()=>`从所有模型中选择`,Hd:()=>`步数限制是安全上限，而不是目标时长。模型完成后会提前停止。提高上限可生成更长的语音，但模型不停止时等待时间也可能增加。`,He:({completed:e,maximum:t})=>`${e} / ${t} steps (limit)`,Hh:()=>`Stopping and releasing the model…`,Hj:()=>`This model pair does not expose a supported audio-generation pipeline. Choose matching Qwen3-TTS Base or Pocket files, not a chat model or vision projector.`,Hk:()=>`Waiting for the inference lane…`,Ql:h,Qm:m,Qt:g};export{S as default};
